public static <T> int writeDelimitedTo(OutputStream out, T message,
                                      Schema<T> schema, LinkedBuffer buffer)
    throws IOException {
    final int size = schema.writeTo(buffer, message);
    final byte[] sizeBytes = new byte[4];
    sizeBytes[0] = (byte) (size & 0xFF);
    sizeBytes[1] = (byte) ((size >> 8) & 0xFF);
    sizeBytes[2] = (byte) ((size >> 16) & 0xFF);
    sizeBytes[3] = (byte) ((size >> 24) & 0xFF);
    out.write(sizeBytes);
    schema.writeTo(out, message);
    return size;
}
