private static Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
    // Check if the type variable has already been resolved.
    ResolvedType resolvedType = (ResolvedType) typeVariable.getAnnotatedType().getType();
    if (resolvedType != null) {
        return resolvedType.getGenericType();
    }
    // Resolve the type variable using the type parameter bounds.
    Type[] bounds = typeVariable.getBounds();
    if (bounds.length == 0 || bounds[0] instanceof Class) {
        return (Class<?>) bounds[0];
    }
    // Recursively resolve the type variable using the first bound.
    Type bound = resolveTypeVariable((TypeVariable<?>) bounds[0], targetType);
    if (bound instanceof Class) {
        return (Class<?>) bound;
    }
    // Fallback to using the raw type if the type variable cannot be resolved.
    return targetType;
}

