protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(Collections.<E, V>emptyList(), graph);
    }
    List<E> path = new ArrayList<>();
    List<V> vertices = new ArrayList<>();
    V currentVertex = graph.getEdgeSource(tour.iterator().next());
    vertices.add(currentVertex);
    for (E edge : tour) {
        V sourceVertex = graph.getEdgeSource(edge);
        V targetVertex = graph.getEdgeTarget(edge);
        if (currentVertex.equals(sourceVertex)) {
            path.add(edge);
            currentVertex = targetVertex;
            vertices.add(currentVertex);
        } else {
            throw new IllegalArgumentException("Tour is not a valid path in the graph");
        }
    }
    return new GraphPathImpl<>(vertices, path, graph);
}

