private List<Pair<Integer,Integer>> computeMinimalSeparators(Graph graph, E edge){
    // Initialize the set of minimal separators
    List<Pair<Integer,Integer>> minimalSeparators = new ArrayList<>();

    // Get the source and target vertices of the edge
    V source = edge.getSource();
    V target = edge.getTarget();

    // Compute the shortest paths between the source and the target
    ShortestPaths<V> shortestPaths = graph.getShortestPaths(source, target);

    // Iterate over each shortest path
    for(Path<V> path : shortestPaths){
        // Get the length of the current path
        int pathLength = path.size();

        // Check if the current path is a unique minimal separator
        boolean isMinimalSeparator = true;
        for(int i = 0; i < pathLength - 1; i++){
            V vertex = path.getVertex(i);
            for(E edge2 : graph.getEdges(vertex)){
                V neighbor = edge2.getOtherVertex(vertex);
                if(graph.getShortestPaths(neighbor, target).size() == pathLength - 1){
                    isMinimalSeparator = false;
                    break;
                }
            }
        }

        // Add the current path to the list of minimal separators if it is unique
        if(isMinimalSeparator){
            minimalSeparators.add(Pair.of(path.getVertex(0).getId(), path.getVertex(pathLength - 1).getId()));
        }
    }

    return minimalSeparators;
}
