protected void append(LoggingEvent event) {
    byte[] message = event.getMessage().getBytes();
    int messageLength = message.length;
    synchronized (outputStreams) {
        Iterator<OutputStream> it = outputStreams.iterator();
        while (it.hasNext()) {
            try {
                it.next().write(message, 0, messageLength);
            } catch (IOException e) {
                it.remove();
                log.warn("Could not write to client. Removing client from list of connected clients.", e);
            }
        }
    }
}

